INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('يتطلبه لإكمال خوارزمية كما أنه لا يرتبط على ما يبدو مع البعد المادي العرفي الذي نألفه. من هذه الشكوك، التي تميز العمل الجاري، ينبع عدم توفر تعريف الخوارزمية التي يناسب كلا من الاستخدام المحدد (بمعنى ما) والاستخدام المجرد لهذا المصطلح. == إضفاء الطابع الرسمي == الخوارزميات ضرورية كى تقوم أجهزة الكمبيوتر بتفعيل البيانات بطريقة عملية. كثير من برنامج الكمبيوتر تحتوي على الخوارزميات التي تقوم بتفصيل تعليمات محددة للكمبيوتر التي ينبغي أن تؤدي (في ترتيب معين) للاضطلاع بمهمة محددة، مثل حساب رواتب الموظفين أو طباعة بطاقات تقارير الطلاب، وبالتالي، يمكن اعتبار الخوارزميات أن تكون أي تسلسل من العمليات التي يمكن محاكاتها من قبل نظام تكامل تورنغ. الكتاب الذين يؤكدون هذه الأطروحة يشملون منسكي (1967)، سافاج (1987) وجورفيتش (2000): منسكي: «ولكننا سوف تحافظ أيضا، مع آلان تورنغ... أن أي إجراء يمكن بطريقة» طبيعية «أن يسمى فعالا، ويمكن في الواقع أن يتحقق أو يدرك من قبل آلة (بسيطة) وبالرغم من أن هذا قد يبدو متطرفا، فالحجج... في صالحها يصعب دحضها». جورفيتش: «... حجة تورنغ الرسمية لصالح أطروحته تبرر أقوى أطروحة: كل خوارزمية يمكن محاكاتها بواسطة آلة تورنغ... وفقا لسافاج [1987]، الخوارزمية هي عملية حسابية محددة بواسطة آلة تورنغ». عادة، عندما تترافق أي خوارزمية مع معلومات المعالجة، تُقْرَأُ البيانات من مصدر المدخلات، وتكتب إلى جهاز إخراج، و / أو تُخزَّن لمزيد من المعالجة. وتعتبر البيانات المخزنة جزءا من الحالة الداخلية للكيان الذي يقوم بأداء الخوارزمية. في الممارسة العملية، تُخزَّن حالة النظام في واحدة أو أكثر من بنية البيانات. لبعض هذه العملية الحسابية، الخوارزمية يجب تعريف الخوارزمية بطريقة صارمة: محددا الطريقة التي تطبق في جميع الظروف الممكنة التي يمكن أن تنشأ. وهذا هو، فإن أي خطوات مشروطة يجب التعامل معها بمنهجية، كل حالة على حدة؛ وإن معايير كل حالة يجب أن تكون واضحة (ومحسوب). لأن الخوارزمية هي قائمة دقيقة لخطوات دقيقة، إن ترتيب الحوسبة يعد أمرا بالغ الأهمية لأداء الخوارزمية دائما. وعادة ما يفترض أن التعليمات تكون مدرجة بشكل صريح، وتوصف بأنها تبدأ من «أعلى» والذهاب إلى «أسفل»، وهي الفكرة التي توصف رسميا من قبل أكثر تدفق عناصر التحكم. حتى الآن، وقد أدت هذه المناقشة لإضفاء الطابع الرسمي على الخوارزمية قد افترضت بناء برمجة أمرية. هذا هو المفهوم الأكثر شيوعا، ومحاولات وصف المهمة في وسائل منفصلة، «ميكانيكية». فريدة من نوعها لهذا المفهوم من الخوارزميات رسميا هو تعيين (علوم الحاسوب)، وتحديد قيمة المتغير. أنه مستمد من الحدس من «الذاكرة» باعتبارها scratchpad. هناك على سبيل المثال أدناه مثل هذا التعيين بالأسفل. لبعض المفاهيم البديلة لما يشكل الخوارزمية انظر البرمجة الوظيفية والبرمجة منطقية. === التعبير عن الخوارزمية === ويمكن التعبير عن الخوارزميات في العديد من أنواع التدوينات، بما في ذلك اللغة الطبيعية وأشباه الكود، المخططات الانسيابية، دراكون-الرسم البياني ولغات البرمجة أو جداول التحكم (التي تُعالج بواسطة المترجمين الفوريين). == تمثيلها == 1- خرائط الانسياب: هو تمثيل مصور للخوارزمية يوضح خطوات حل المشكلة من البداية إلى النهاية مع إخفاء التفاصيل لإعطاء الصورة العامة للحل. و يمكن تصنيفها إلى أصناف أربعة هي: مخططات سير العمليات التتابعية (Sequential Flowcharts). مخططات سير العمليات ذات التفرع (Branched Flowcharts). مخططات سير العمليات ذات التكرار والدوران (Loop Flowcharts). مخططات سير العمليات ذات الاختيار (Selection Flowcharts). 2-الشفرة الوصفية (Pseudocode): وصف الخوارزمية بلغات البشر كالإنجليزية أو الفرنسية أو العربية بطريقة مشابهه للغات البرمجة ولكن بدون أي انتماء لها. البعض يستخدم الكثير من التفاصيل (لتصبح قريبة من لغات البرمجة) والبعض الآخر يستخدم القليل (أي أقرب للغة البشر)... فلا قاعدة معينة لكتابة هذا النوع من الشفرات. == خوارزميات حاسوبية == في أنظمة الحاسوب، تمثل الخوارزميات في الأساس صورة من منطق أعيد كتابته بواسطة (برمجيات) ليصبح أكثر فعالية يمكن استغلاله في الحواسيب والحصول على النتائج (مخرجات) من بيانات معطاة (مدخلات). === قواعد البرمجة ===', 'Wikipedia Arabic - خوارزمية', 'و يمكن تصنيفها إلى أصناف أربعة هي: (part 2)', 'علوم الحاسب', '[-0.0605469,0.0289917,0.0420837,-0.0251923,0.0490112,-0.0218048,0.0186615,-0.0151215,-0.0205383,0.0173035,0.0281982,-0.0019131,0.0298615,-0.0249634,0.0153351,0.0258484,-0.0335693,0.0078812,0.0263519,-0.0154190,0.0571594,-0.0