INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('التتابع Sequence
تتابع الاوامر حيث ينفذها جهاز الحاسوب حسب الترتيب.


== أمثلة ==


=== مثال الترتيب ===

يُعدّ البحث عن العدد الأكبر في قائمة (غير مرتبة) من الأعداد أحد أبسط الخوارزميات. يتطلب الحل فحص كل عدد في القائمة، بحيث يُفحص عدد واحد في كل خطوة. يمكن صياغة هذه الخوارزمية البسيطة بلغة برمجية عليا كما يلي:', 'Wikipedia Arabic - خوارزمية', 'التتابع Sequence', 'علوم الحاسب', '[-0.0075951,0.0319824,0.0708008,-0.0249939,-0.0020008,0.0240173,-0.0074005,0.0061569,-0.0316772,0.0240936,0.0090637,-0.0414124,0.0261841,-0.0371094,0.0343323,0.0202484,0.0187378,-0.0049210,-0.0081406,0.0017958,0.0411987,-0.0473022,0.0032406,0.0416260,0.0000502,-0.0519409,0.0046844,0.0414124,-0.0006361,-0.0310059,0.0373840,-0.0296021,-0.0003209,0.0089111,0.0134888,-0.0086823,-0.0277557,-0.0047836,0.0123520,0.0473328,0.0245056,0.0254517,-0.0127411,-0.0182190,0.0154648,0.0112839,-0.0319214,-0.0466919,0.0101395,0.0415649,0.0222015,0.0236664,-0.0044632,0.0751953,0.0259094,-0.0018997,-0.0208740,0.0372314,0.0648804,-0.0195618,-0.0192871,0.0197449,-0.0189209,0.0242004,-0.0312042,-0.0033188,-0.0231018,0.0278931,0.0089417,-0.0164795,-0.0600586,0.0020218,-0.0101929,0.0207825,0.0260010,0.0060921,0.0005727,0.0188141,0.0235291,-0.0207672,0.0375366,-0.0747070,0.0414429,-0.0402832,0.0505676,-0.0265503,-0.0464783,-0.0034008,-0.0113678,-0.0830078,-0.0420227,0.0502014,-0.0103226,0.0030575,0.0266113,-0.0017834,0.0278778,-0.0177612,-0.0402222,0.0080185,0.0386963,-0.0382080,-0.0118027,-0.0633545,0.0087433,-0.0296478,-0.0391235,0.0007992,-0.0477600,-0.0062065,-0.0124969,-0.0418701,-0.0046692,0.0088425,0.1044312,0.0144806,0.0293579,0.0269012,-0.0089417,-0.0084381,0.0138702,-0.0220795,0.0244293,-0.0254364,-0.0385742,0.0000818,0.0189819,-0.0169525,0.0047951,0.0298615,0.0524597,-0.0243073,-0.0356445,0.0310516,0.0358276,-0.0144043,-0.0355225,0.0187988,-0.0049210,0.0380249,-0.0088806,-0.0212402,-0.0003817,0.0244446,0.0042419,0.0032406,-0.0110092,0.0498962,0.0246124,0.0141296,-0.0141449,-0.0085983,-0.0203247,0.0436707,0.0242462,-0.0179291,-0.0689087,-0.0254822,-0.0195923,0.0292206,-0.0179291,-0.0512085,0.0674438,0.0065308,-