INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('افرض أن العنصر الأول هو الأكبر.
انظر إلى كل عنصر من عناصر القائمة المتبقية وإذا كان أكبر من العنصر الأكبر حتى الآن، قم بوضع علامة عليه.
يكون العنصر المعلم الأخير هو أكبر عنصر في القائمة عند انتهاء العملية.


=== خوارزمية إقليدس ===
تظهر خوارزمية إقليدس في المسألة الثانية من كتابه («نظرية الأعداد الأساسية»). يعرض إقليدس المسألة: «إذا كان لدينا عددان أوليان فيما بينهما، لإيجاد قياسهما المشترك الأكبر». يقوم بتعريف «العدد [بأنه] متعدد مؤلف من وحدات»:، عدد حسابي، عدد موجب لا يتضمن الصفر. ومن أجل «القياس» فيعني أن نضع قطعة قياس طولية s بشكل متعاقب (q من المرات) على طول القطعة الأطول l حتى يتبقى الجزء r أقل من القطعة الأقصر s. في العبارات الحديثة نقول، الباقي r = l - q*s، q هي حاصل القسمة، r «باقي القسمة», الجزء الكسري المتبقي بعد إجراء القسمة.


== برنامج بسيط لمحاكاة خوارزمية إقليدس ==
المثال التالي بلغة بيسك يمثل برنامجاً بسيطاً ينفذ خوارزمية إقليدس:


== التحليل الخوارزمي ==
من المهم كثيرا أن نعرف كم من مورد معين (مثل الوقت أو التخزين) مطلوب نظريا لخوارزمية معينة. وقد وضعت طرق لتحليل الخوارزميات للحصول على هذه الإجابات الكمية (تقديرات)، على سبيل المثال، خوارزمية الترتيب أعلاه لتقدير الوقت الذي قد تستغرقه في عملية التنفيذ نعبر عنه ب O(n) ، وذلك باستخدام O تدوين كبيرة مع n يمثل طول القائمة (Array). في جميع تعليمات هذه الخوارزمية تحتاج فقط إلى تذكر متغيرين: العدد الأكبر الذي عثرت عليه الى حد الآن، وموقعها الحالي في قائمة المدخلات. لذلك يجب أن نعبر عنها عبر(O(1، أي المساحة المطلوبة لتخزين أرقام المدخلات لا تحصى.
قد تقوم عدة خوارزميات بتنفيذ المهمة نفسها من خلال مجموعة مختلفة من التعليمات في وقت أقل أو أكثر، مساحة، أو جهد من غيرها. على سبيل المثال، خوارزمية البحث الثنائي (binary search) عادة ما تكون أكثر كفاءة وسرعة من البحث المتتابع (linear search) عندما تستخدم لعمليات البحث على القوائم التي رتبت من قبل.


== تسريع الإف إف تي ==
لإضفاء التحسينات الممكنة حتى في بعض الخوارزميات «المبنية بشكل جيد»، وهذا ابتكار هام يتعلق بخوارزميات الإف إف تي (التي تستخدم بشكل كبير جدا في مجال معالجة الصور)، قد تمكن من خفض عدد مرات المعالجة بمعامل يصل إلى 10000 مرة. أثر هذا التسريع إلى تمكين الأجهزة الحاسوبية المحمولة (فضلا عن غيرها من الأجهزة) من استهلاك طاقة أقل.


